<?php
require '../auth.php'; require '../../config/koneksi.php'; require_once '../../includes/csrf.php';
$search=trim($_GET['search']??''); $kategori=max(0,(int)($_GET['kategori']??0)); $page=max(1,(int)($_GET['page']??1)); $limit=6; $start=($page-1)*$limit;
$where='WHERE a.deleted_at IS NULL'; if($kategori>0)$where.=" AND a.id_kategori=$kategori"; if($search!==''){$safe=mysqli_real_escape_string($conn,$search);$where.=" AND a.judul LIKE '%$safe%'";}
$total=(int)(mysqli_fetch_assoc(mysqli_query($conn,"SELECT COUNT(*) total FROM artikel a $where"))['total']??0);$totalPages=max(1,(int)ceil($total/$limit));
$data=mysqli_query($conn,"SELECT a.*,k.nama_kategori FROM artikel a LEFT JOIN kategori_kegiatan k ON a.id_kategori=k.id_kategori $where ORDER BY a.tanggal DESC LIMIT $start,$limit");$categories=mysqli_query($conn,'SELECT * FROM kategori_kegiatan ORDER BY nama_kategori');
$page_title='Kelola Artikel';$active_menu='kegiatan';$admin_base='..';include '../includes/header.php';
?>
<div class="admin-page-header"><div><h1>Artikel Kegiatan</h1><p>Kelola artikel dan dokumentasi kegiatan masjid</p></div><a class="btn-tambah" href="tambah.php">+ Tambah Artikel</a></div>
<div class="content-card"><form class="filter-bar article-filter admin-filter-bar" method="GET"><input class="admin-filter-search" name="search" value="<?= htmlspecialchars($search,ENT_QUOTES,'UTF-8') ?>" placeholder="Cari artikel..."><select class="admin-filter-select" name="kategori"><option value="0">Semua Kategori</option><?php while($cat=mysqli_fetch_assoc($categories)):?><option value="<?= (int)$cat['id_kategori'] ?>" <?= $kategori===(int)$cat['id_kategori']?'selected':'' ?>><?= htmlspecialchars($cat['nama_kategori'],ENT_QUOTES,'UTF-8') ?></option><?php endwhile;?></select><button class="btn admin-filter-action"><i class="fa fa-filter"></i> Filter</button></form>
<div class="card-grid"><?php if(mysqli_num_rows($data)===0):?><div class="empty-state compact-empty"><i class="fa fa-newspaper"></i><h2>Artikel tidak ditemukan</h2><p>Artikel yang sesuai pencarian akan tampil di sini.</p></div><?php endif;?><?php while($row=mysqli_fetch_assoc($data)):?><article class="artikel-card"><img src="../../uploads/kegiatan/<?= rawurlencode($row['gambar']) ?>" onerror="this.src='../../assets/img/banner.jpg'" alt=""><div class="artikel-card-body"><p class="kategori-badge"><?= htmlspecialchars($row['nama_kategori']??'Umum',ENT_QUOTES,'UTF-8') ?></p><h3><?= htmlspecialchars($row['judul'],ENT_QUOTES,'UTF-8') ?></h3><p><?= htmlspecialchars(mb_strimwidth($row['deskripsi'],0,100,'...'),ENT_QUOTES,'UTF-8') ?></p><div class="aksi"><a class="btn-edit" href="edit.php?id=<?= (int)$row['id_artikel'] ?>">Edit</a><form method="POST" action="hapus.php" class="inline-action" onsubmit="return confirm('Data akan dipindahkan ke Tempat Sampah dan masih dapat dipulihkan.')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$row['id_artikel'] ?>"><button class="btn-hapus" type="submit">Hapus</button></form></div></div></article><?php endwhile;?></div>
<?php if ($total > 0): ?><div class="pagination"><?php for($i=1;$i<=$totalPages;$i++):?><a class="<?= $i===$page?'active-page':'' ?>" href="?page=<?= $i ?>&search=<?= urlencode($search) ?>&kategori=<?= $kategori ?>"><?= $i ?></a><?php endfor;?></div><?php endif; ?></div>
<?php include '../includes/footer.php';?>
